starterCodeJson.code:
// Question 1 — the cover page of the SRS template (Wiegers): fill every field, remove every <placeholder>.
const COVER = {
  title: 'Software Requirements Specification',
  project: '<Project name>',
  version: '<1.0>',
  preparedBy: '<Your full name - Student ID>',
  organization: '<Organization>',
  dateCreated: '<yyyy-mm-dd>',
};

// Question 2 — context diagram as a Mermaid flowchart (paste into https://mermaid.live to see it).
// The system = ONE circle. External entities = rectangles. One labelled arrow per direction; label = the DATA.
const CONTEXT_DIAGRAM = `
flowchart LR
  S((System name))
  E1[External entity] -->|data in| S
  S -->|data out| E1
`;

// Question 3 — use case diagram (PlantUML: paste into https://www.plantuml.com/plantuml) + the two tables of the template.
const USE_CASE_DIAGRAM = `
@startuml
left to right direction
actor "Actor name" as A1
rectangle "System name" {
  usecase "Verb Object" as UC1
}
A1 --> UC1
@enduml
`;

// Table "# | Actor | Description" — one object per actor of the diagram (same names).
const ACTORS = [
  { name: 'Actor name', description: '' },
];

// Table "# | Use Case | Actors | Description" — one object per use case (same names as the diagram).
const USE_CASES = [
  { id: 'UC-01', name: 'Verb Object', actors: ['Actor name'], description: '' },
];

// Question 4 — state transition diagram (Mermaid stateDiagram-v2) + the state table of the template.
const STATE_DIAGRAM = `
stateDiagram-v2
  [*] --> FirstState
  FirstState --> SecondState : event [guard] / action
  SecondState --> [*]
`;

// Table "# | State | Description" — one object per state of the diagram.
const STATES = [
  { name: 'FirstState', description: '' },
];

solutionCodeJson.code:
// Question 1 — copy the system name EXACTLY from the paper; the grader cannot know your name, any real one passes.
const COVER = {
  title: 'Software Requirements Specification',
  project: 'SkillSwap Campus Peer-Tutoring Platform',
  version: '1.0',
  preparedBy: 'Nguyen Van An - SE180123',
  organization: 'FPT University, Ho Chi Minh City campus',
  dateCreated: '2026-11-05',
};

// Question 3 — use case diagram consistent with Question 2 (same actors), plus the actor and use case tables.
const USE_CASE_DIAGRAM = `@startuml
left to right direction
actor Learner
actor Tutor
actor "Academic Officer" as AO
actor Moderator
actor "Platform Administrator" as AD
actor "Student Information System" as SIS
actor "Campus E-wallet" as EW
actor "Library Room Booking System" as LR
actor "Video Meeting Service" as VM
actor "Notification Service" as NS
rectangle "SkillSwap Campus Peer-Tutoring Platform" {
  usecase "Sign In" as UC1
  usecase "Apply as Tutor" as UC2
  usecase "Check Tutor Eligibility" as UC3
  usecase "Review Tutor Application" as UC4
  usecase "Search Tutors" as UC5
  usecase "Request Session" as UC6
  usecase "Respond to Session Request" as UC7
  usecase "Pay for Session" as UC8
  usecase "Book Study Room" as UC9
  usecase "Create Meeting Link" as UC10
  usecase "Cancel Session" as UC11
  usecase "Rate Session" as UC12
  usecase "Report Session Problem" as UC13
  usecase "Resolve Dispute" as UC14
  usecase "Release Tutor Payout" as UC15
  usecase "Configure Prices and Rules" as UC16
  usecase "View Monthly Report" as UC17
  usecase "Send Notification" as UC18
}
Learner --> UC1
Tutor --> UC1
AO --> UC1
Moderator --> UC1
AD --> UC1
UC1 --> SIS
Tutor --> UC2
UC2 ..> UC3 : <<include>>
UC3 --> SIS
AO --> UC4
Learner --> UC5
Learner --> UC6
Tutor --> UC7
Learner --> UC8
UC8 --> EW
UC9 ..> UC8 : <<extend>>
UC9 --> LR
UC10 ..> UC8 : <<extend>>
UC10 --> VM
Learner --> UC11
Learner --> UC12
Learner --> UC13
Moderator --> UC14
UC15 --> EW
AD --> UC16
AD --> UC17
UC7 ..> UC18 : <<include>>
UC18 --> NS
@enduml
`;

const ACTORS = [
  {
    name: 'Learner',
    description: 'A student who searches tutors, requests and pays for sessions, cancels, rates them or reports problems.',
  },
  {
    name: 'Tutor',
    description: 'A senior student approved to tutor a subject who accepts or declines session requests and is paid after sessions.',
  },
  {
    name: 'Academic Officer',
    description: 'University staff who review tutor applications after the system has checked GPA and subject grade.',
  },
  {
    name: 'Moderator',
    description: 'Platform staff who examine reported sessions and decide to refund the learner or pay the tutor.',
  },
  {
    name: 'Platform Administrator',
    description: 'Sets prices per subject level, the commission rate and penalty rules, and reads monthly reports.',
  },
  {
    name: 'Student Information System',
    description: 'External university system that authenticates students and provides their GPA and subject grades.',
  },
  {
    name: 'Campus E-wallet',
    description: 'External payment service that executes session payments, refunds and tutor payouts in campus credits.',
  },
  {
    name: 'Library Room Booking System',
    description: 'External library system that reserves a study room for in-person sessions.',
  },
  {
    name: 'Video Meeting Service',
    description: 'External service that creates the meeting link for online sessions.',
  },
  {
    name: 'Notification Service',
    description: 'External university service that delivers the e-mails and push notifications sent by SkillSwap.',
  },
];

const USE_CASES = [
  {
    id: 'UC-01',
    name: 'Sign In',
    actors: ['Learner', 'Tutor', 'Academic Officer', 'Moderator', 'Platform Administrator', 'Student Information System'],
    description: 'A user signs in with the university account; the SIS authenticates the user.',
  },
  {
    id: 'UC-02',
    name: 'Apply as Tutor',
    actors: ['Tutor'],
    description: 'A student applies to tutor a subject on SkillSwap.',
  },
  {
    id: 'UC-03',
    name: 'Check Tutor Eligibility',
    actors: ['Student Information System'],
    description: 'Included in every application: GPA ≥ 3.2 and subject grade ≥ 8.0 are checked with the SIS.',
  },
  {
    id: 'UC-04',
    name: 'Review Tutor Application',
    actors: ['Academic Officer'],
    description: 'The academic officer approves or rejects an eligible tutor application.',
  },
  {
    id: 'UC-05',
    name: 'Search Tutors',
    actors: ['Learner'],
    description: 'The learner finds tutors by subject, rating and available time slots.',
  },
  {
    id: 'UC-06',
    name: 'Request Session',
    actors: ['Learner'],
    description: 'The learner requests a session with a tutor for a time slot, online or in person.',
  },
  {
    id: 'UC-07',
    name: 'Respond to Session Request',
    actors: ['Tutor'],
    description: 'The tutor accepts or declines a request within 24 hours.',
  },
  {
    id: 'UC-08',
    name: 'Pay for Session',
    actors: ['Learner', 'Campus E-wallet'],
    description: 'The learner pays the session price in credits within 2 hours of acceptance.',
  },
  {
    id: 'UC-09',
    name: 'Book Study Room',
    actors: ['Library Room Booking System'],
    description: 'Extension of paying for an in-person session: a study room is reserved in the library system.',
  },
  {
    id: 'UC-10',
    name: 'Create Meeting Link',
    actors: ['Video Meeting Service'],
    description: 'Extension of paying for an online session: a meeting link is obtained from the video service.',
  },
  {
    id: 'UC-11',
    name: 'Cancel Session',
    actors: ['Learner'],
    description: 'The learner cancels a paid session at least 12 hours before it starts and is refunded.',
  },
  {
    id: 'UC-12',
    name: 'Rate Session',
    actors: ['Learner'],
    description: 'Within 48 hours after the session, the learner rates the tutor.',
  },
  {
    id: 'UC-13',
    name: 'Report Session Problem',
    actors: ['Learner'],
    description: 'Within 48 hours after the session, the learner reports a problem for the moderator to examine.',
  },
  {
    id: 'UC-14',
    name: 'Resolve Dispute',
    actors: ['Moderator'],
    description: 'The moderator decides to refund the learner or to pay the tutor for a reported session.',
  },
  {
    id: 'UC-15',
    name: 'Release Tutor Payout',
    actors: ['Campus E-wallet'],
    description: '48 hours after an undisputed session, the price minus 10% commission is paid to the tutor.',
  },
  {
    id: 'UC-16',
    name: 'Configure Prices and Rules',
    actors: ['Platform Administrator'],
    description: 'The administrator sets prices per level, the commission rate and penalty rules.',
  },
  {
    id: 'UC-17',
    name: 'View Monthly Report',
    actors: ['Platform Administrator'],
    description: 'The administrator reads sessions, revenue and average tutor ratings per month.',
  },
  {
    id: 'UC-18',
    name: 'Send Notification',
    actors: ['Notification Service'],
    description: 'Included whenever a user must be informed: the notification service delivers the message.',
  },
];

// Question 4 — state machine of the object: conditions as states, event [guard] / action on every transition.
const STATE_DIAGRAM = `stateDiagram-v2
  [*] --> Requested : learner requests a session
  state "In Progress" as InProgress
  state "Awaiting Feedback" as AwaitingFeedback
  state "No-show" as NoShow
  Requested --> Accepted : tutor accepts / notify learner
  Requested --> Declined : tutor declines / notify learner
  Requested --> Expired : 24 hours elapsed [no response from tutor]
  Accepted --> Confirmed : payment succeeded / book room or link
  Accepted --> Cancelled : 2 hours elapsed [not paid]
  Confirmed --> Cancelled : learner cancels [12+ hours before start] / refund
  Confirmed --> InProgress : start time [tutor joined]
  Confirmed --> NoShow : 15 min after start [tutor absent] / refund
  InProgress --> AwaitingFeedback : session ends
  AwaitingFeedback --> Disputed : problem reported [within 48 hours]
  AwaitingFeedback --> Completed : 48 hours elapsed [no problem] / pay tutor
  Disputed --> Completed : moderator rules for tutor / pay tutor
  Disputed --> Refunded : moderator rules for learner / refund
  Declined --> [*]
  Expired --> [*]
  Cancelled --> [*]
  NoShow --> [*]
  Completed --> [*]
  Refunded --> [*]
`;

const STATES = [
  {
    name: 'Requested',
    description: 'The learner has requested a time slot and is waiting for the tutor’s answer (at most 24 hours).',
  },
  { name: 'Accepted', description: 'The tutor accepted; the learner must pay within 2 hours to keep the slot.' },
  { name: 'Declined', description: 'The tutor declined the request; the learner may request another tutor.' },
  { name: 'Expired', description: 'The tutor did not answer within 24 hours, so the request lapsed.' },
  {
    name: 'Confirmed',
    description: 'The session is paid and a room or meeting link is reserved; it waits for its start time.',
  },
  {
    name: 'Cancelled',
    description: 'The session was not paid in time or the learner cancelled at least 12 hours before it.',
  },
  {
    name: 'In Progress',
    description: 'The start time has come and the tutor has joined; tutoring is taking place.',
  },
  {
    name: 'No-show',
    description: 'The tutor had not joined 15 minutes after the start; the learner has been refunded.',
  },
  {
    name: 'Awaiting Feedback',
    description: 'The session has ended; the learner has 48 hours to rate it or report a problem.',
  },
  {
    name: 'Disputed',
    description: 'The learner reported a problem and a moderator must decide who receives the money.',
  },
  {
    name: 'Completed',
    description: 'The session closed without a problem or the moderator ruled for the tutor; the tutor is paid.',
  },
  {
    name: 'Refunded',
    description: 'The moderator ruled for the learner and the price has been returned in credits.',
  },
];

